import sys

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    n = data[0]
    nums = data[1:]

    grid = [nums[i * n:(i + 1) * n] for i in range(n)]

    r0 = c0 = -1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                r0, c0 = i, j
                break
        if r0 != -1:
            break

    magic_sum = 0
    for i in range(n):
        if 0 not in grid[i]:
            magic_sum = sum(grid[i])
            break

    missing = magic_sum - sum(grid[r0])

    sys.stdout.write(f"{missing}\n{r0 + 1}\n{c0 + 1}\n")

if __name__ == "__main__":
